mapper.select:
SELECT c.drink_category_id AS categoryId, c.category_name AS categoryName, c.shop_id AS shopId, s.shop_name AS shopName FROM drink_categories c INNER JOIN shops s ON c.shop_id = s.shop_id WHERE c.is_deleted = false
AND c.shop_id = #{currentUserShopId}
ORDER BY s.shop_name ASC, c.category_name ASC
